fn qs(a:[]const i64,k:usize)i64{if(a.len==1)return a[0];const p=a[0];var small:[64]i64=@splat(0);var big:[64]i64=@splat(0);var ns:usize=0;var nb:usize=0;for(a[1..])|x|{if(x<p){small[ns]=x;ns+=1;}else if(x>p){big[nb]=x;nb+=1;}}if(k==ns+1)return p;if(k<=ns)return qs(small[0..ns],k);return qs(big[0..nb],k-ns-1);}
export fn kth_order_statistic(v:[*]const i64,n:usize)i64{if(n<2 or n>65)return -1;const k=v[0];if(k<1 or k>=@as(i64,@intCast(n)))return -1;var a:[64]i64=@splat(0);for(1..n)|i|{const x=v[i];if(x< -10000 or x>10000)return -1;for(1..i)|j|{if(x==v[j])return -1;}a[i-1]=x;}return qs(a[0..n-1],@intCast(k));}
